extra.raw_output:
{
  "tools": [
    {
      "name": "module_new",
      "description": "Create a new empty module",
      "inputSchema": {
        "type": "object",
        "properties": {
          "channels": {
            "type": "integer",
            "description": "Even channel count 2..32"
          },
          "name": {
            "type": "string",
            "description": "Song name"
          }
        },
        "additionalProperties": false
      }
    },
    {
      "name": "module_load",
      "description": "Load a module from disk",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "module_info",
      "description": "Return current module metadata",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "additionalProperties": false
      }
    },
    {
      "name": "pattern_set_cell",
      "description": "Set one pattern cell",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "row": {
            "type": "integer"
          },
          "channel": {
            "type": "integer"
          },
          "note": {
            "type": [
              "integer",
              "string"
            ]
          },
          "instrument": {
            "type": "integer"
          },
          "volume": {
            "type": "integer"
          },
          "effect": {
            "type": "integer"
          },
          "effect_param": {
            "type": "integer"
          }
        },
        "required": [
          "pattern",
          "row",
          "channel"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "pattern_get_cell",
      "description": "Read one pattern cell",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "row": {
            "type": "integer"
          },
          "channel": {
            "type": "integer"
          }
        },
        "required": [
          "pattern",
          "row",
          "channel"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_load",
      "description": "Load a sample into an instrument",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer",
            "description": "Sample slot 0..15"
          }
        },
        "required": [
          "path",
          "instrument"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "module_save",
      "description": "Save the current module",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "format": {
            "type": "string",
            "enum": [
              "xm",
              "mod"
            ]
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "module_render",
      "description": "Render the current module to WAV",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "rate": {
            "type": "integer"
          },
          "bits": {
            "type": "integer"
          },
          "amp": {
            "type": "integer"
          },
          "loops": {
            "type": "integer"
          },
          "start": {
            "type": "integer"
          },
          "stop": {
            "type": "integer"
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "song_set",
      "description": "Set song metadata fields",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string"
          },
          "bpm": {
            "type": "integer"
          },
          "speed": {
            "type": "integer"
          },
          "length": {
            "type": "integer"
          },
          "loop_start": {
            "type": "integer"
          },
          "channels": {
            "type": "integer"
          }
        },
        "additionalProperties": false
      }
    },
    {
      "name": "order_set",
      "description": "Set one song order entry",
      "inputSchema": {
        "type": "object",
        "properties": {
          "position": {
            "type": "integer"
          },
          "pattern": {
            "type": "integer"
          }
        },
        "required": [
          "position",
          "pattern"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "pattern_clear",
      "description": "Clear all cells in a pattern",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          }
        },
        "required": [
          "pattern"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "pattern_set_length",
      "description": "Set pattern row count",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "rows": {
            "type": "integer"
          }
        },
        "required": [
          "pattern",
          "rows"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "cell_clear",
      "description": "Clear one pattern cell",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "row": {
            "type": "integer"
          },
          "channel": {
            "type": "integer"
          }
        },
        "required": [
          "pattern",
          "row",
          "channel"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_save",
      "description": "Save a sample to disk",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer"
          },
          "format": {
            "type": "string",
            "enum": [
              "wav",
              "iff",
              "raw"
            ]
          }
        },
        "required": [
          "path",
          "instrument"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_set",
      "description": "Set sample metadata",
      "inputSchema": {
        "type": "object",
        "properties": {
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer"
          },
          "name": {
            "type": "string"
          },
          "volume": {
            "type": "integer"
          },
          "panning": {
            "type": "integer"
          },
          "finetune": {
            "type": "integer"
          },
          "relative_note": {
            "type": "integer"
          },
          "loop_start": {
            "type": "integer"
          },
          "loop_length": {
            "type": "integer"
          },
          "flags": {
            "type": "integer"
          }
        },
        "required": [
          "instrument"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_create_from_pcm",
      "description": "Create sample from base64 PCM",
      "inputSchema": {
        "type": "object",
        "properties": {
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer"
          },
          "pcm": {
            "type": "string"
          },
          "encoding": {
            "type": "string",
            "enum": [
              "int16",
              "float32"
            ]
          },
          "name": {
            "type": "string"
          }
        },
        "required": [
          "instrument",
          "pcm"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "instrument_set",
      "description": "Set instrument metadata",
      "inputSchema": {
        "type": "object",
        "properties": {
          "instrument": {
            "type": "integer"
          },
          "name": {
            "type": "string"
          }
        },
        "required": [
          "instrument"
        ],
        "additionalProperties": false
      }
    }
  ]
}

