# XM note encoding: C-0 = 1, C#0 = 2, ..., B-0 = 12, C-1 = 13, etc.
# Note 0 means no note

def note_xm(name):
    """Convert note name to XM note number (C-0 = 1)"""
    if name == '---':
        return 0
    if name == '===':
        return 97  # Note off
    notes = {'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5, 'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11}
    if '#' in name:
        n = name[:2]
        octave = int(name[2])
    else:
        n = name[0]
        octave = int(name[2])
    return 1 + notes[n] + octave * 12

# Test
print(f"C-4 = {note_xm('C-4')}")  # Should be 49
print(f"A-4 = {note_xm('A-4')}")  # Should be 58
print(f"A-2 = {note_xm('A-2')}")  # Should be 34
print(f"C-5 = {note_xm('C-5')}")  # Should be 61
PYEOF"}

