add_note(4, 0, 6, note('A-3'), 7)
add_note(4, 32, 6, note('E-3'), 7)

with open('/workspace/patterns_fixed.json', 'w') as f:
    json.dump(batch_commands, f)

print(f"Created {len(batch_commands)} commands")
